using CampaignCore;

namespace CampaignCreator;

internal sealed record GuideEntry(string Label, string Description);

// Keep selectable catalogs tied to the same source as the editors. These are
// explanations only; opening the guide must never create or save user content.
internal static class StudioGuideReference
{
    internal static IReadOnlyList<GuideEntry> For(string topic) => topic switch
    {
        "start" => [
            new("Campaigns", "Create new opens a campaign draft; Edit existing opens a saved campaign. Import installs a shared campaign and Upload shares one."),
            new("Players", "Select Skater or Goalie before Create new, Edit existing or Import. New players made from Home save to the player library."),
            new("Teams", "Select Player team or Campaign opponent before creating, editing or importing. New teams made from Home save to their corresponding library."),
            new("Select campaign", "Saves immediately. None (base game) disables custom campaigns on the next game launch."),
            new("Copy vanilla campaign", "Create a draft from a native squad, retaining native roster/opponent identities, candidate pools and unedited settings. Name and save it, then select it on Home. Editable overrides still follow native gameplay requirements."),
            new("Set default", "Set the look that new players and teams start with."),
            new("Head Editor", "Create, edit and install a custom head project."),
            new("Help / F1", "Explains the current page or dialog. Continue and Previous browse explanations; Point again reveals the control; Done or Close dismisses Help. Reopen Help after switching pages or tabs."),
            new("Studio guide", "Search every topic and its option listings. All search words must match. Clear search restores the full list; Related topics and Back to previous topic navigate articles."),
            new("Join Discord for help", "Open the community Discord invite in your browser for help with the mod and Studio."),
            new("GitHub", "Open the project repository in your browser for downloads, documentation and issues."),
            new("Read game artwork", "Rebuild previews and base-game roster records from the installed game. If the game cannot be found, choose its installation folder. Later skips the startup prompt."),
            new("Uninstall", "Save your edits and close Tape to Tape. Confirm to close Studio and open the Windows uninstaller for Studio and the bundled mod. Saved campaigns, players and custom heads are kept. Cancel leaves Studio open."),
            new("Report a bug", "Review the report and optional setup/log details, then open GitHub. You submit the issue yourself in the browser.")],
        "campaign" => [
            new("Name your campaign", "Names a new campaign's saved folder. An unnamed save keeps a working draft; an existing saved campaign has a fixed heading."),
            new("Open opponents", "Manage opponents and assign them to match nodes. + New opponent creates a team directly in this campaign."),
            new("Open superstar/bench options", "Open Choose campaign team to select player teams and shared starting pools. Each team has its own preset and Squad behaviors. + Add player team opens a new campaign team."),
            new("Open map editor", "Edit the campaign's route and map sequence. Individual map cards jump to that map."),
            new("Choose free agents", "Set the recruitment pool."),
            new("Edit reward pools", "Set allowed random rewards by category."),
            new("Needs attention", "Links to unassigned opponents and nodes referencing missing teams."),
            new("Offside in every match", "Enable the campaign's offside rule. Save campaign keeps the setting."),
            new("Offside penalty", "Player's setting, Whistle, Lose Puck or Knockout. Enabled only when campaign offside is on."),
            new("Save campaign", "Save campaign settings and pending pool/map edits. Players and teams have their own save buttons."),
            new("Back", "Returns from a section to the overview. Back from the overview returns Home and discards unsaved campaign edits."),
            new("Import / Upload", "Import from file or Download and install brings in a campaign. Keep both gives a duplicate a new name; Replace mine first keeps the old campaign in campaign_backups. Upload publishes the saved campaign and referenced logos to the public community folder.")],
        "sources" => [
            new("Base game", "Teams and players decoded from your installed Tape to Tape by Read game artwork. Ordinary imports copy editable fields, not native identity checks. Copy vanilla campaign on Home retains native identities. No running game is required."),
            new("In-game custom", "Custom content read from the game's save folder, including Studio exports. Copies with the same name remain separate and show their dates."),
            new("Campaign custom", "Content in your campaigns and the Studio player/opponent libraries."),
            new("Player team library", "Team imports add this as their first source tab. Copies a saved player team and its roster."),
            new("Search", "Filters entries in the selected source tab by name."),
            new("Import selected", "Accepts the selected source; the destination workflow creates its own editable copy."),
            new("Import from file…", "Choose a player .txt file or team.txt for the requested content type."),
            new("Needs attention / Nothing selected", "Complete required fields after importing. Missing source values are not silently replaced with arbitrary choices.")],
        "players" => [
            new("Name / Number", "Display name and jersey number; these do not grant a native identity. Position is assigned by the roster slot."),
            new("Number style", "Inherit team follows the team default; Regular, Roman numerals or Prison overrides it for this player. Independent of Team equipment. Native imports retain each player's format, and the mod preserves resolved styles in Play Now exports."),
            new("Counts as Prince for Crusader brawls", "Qualifies this skater only as the Crusader bodycheck-brawl victim. The opponent needs Bodycheck brawl enabled on an Elite match; a human-controlled attacker must hit the victim during charged-shot windup, subject to native challenge gates. No other Prince identity is granted."),
            new("Appearance", "Head or mask, equipment, logo, home/away preview and the player's own colors."),
            new("Pass Read", "Native range 0–1. Zero uses normal pass reaction. Any positive value enables quick pass reading only when the current difficulty permits it; higher values do not scale this effect. Goalies only. Save changes keeps it and mod-backed Play Now exports preserve fractional values."),
            new("Details & attributes", "Skater size, size offset, handedness and four playing stats; goalies use their separate attribute set."),
            new("Ability", "Optional skater special action. Opponent choices are limited to abilities supported by AI; goalies have no ability selector."),
            new("Talents / Goalie Talents", "Search and select role-specific effects. These assignments are separate from campaign reward pools."),
            new("Preview team", "For starting superstars, choose the campaign player team shown in the preview. It does not assign the superstar to that team."),
            new("Save changes", "Validate and save the player. A newly created Home player saves directly to the library."),
            new("Back to team", "Shown when opened from a team roster. Returns to that roster; save player edits first."),
            new("Home", "Leave the player editor and discard unsaved edits."),
            new("Export to Play Now", "Write separate game content from the current fields. This does not save the Studio player.")],
        "appearance" => [
            new("Team equipment", "On uses team styles. Off allows player styles. The skater stick style is always personal; kit colors still come from the team."),
            new("Head / Goalie mask", "Skaters choose their own head. A goalie uses a mask, shared by the home and away kits. Some skater heads have no selectable helmet variant; physical equipment still follows native rules."),
            new("Helmet", "Team colors equips the ordinary native helmet without a talent or stat bonus. None removes that ordinary starting helmet; talent, transformation and reward helmets keep their native rules. Home Helmet controls physical starting equipment; Helmet Away does not independently equip, remove or replace the physical helmet. Loss, drops and restoration use native equipment state. Selecting the native Wing style equips its matching equipment without adding a talent; native Wing drop rules apply. Other special helmet artwork requires its native equipment source."),
            new("Jersey / Biceps / sleeves", "The jersey selects matching sleeves. Biceps / sleeves appears in Premade mode to change them separately."),
            new("Gloves / Pants / Socks", "Choose skater styles. Same as jersey lets socks follow the jersey."),
            new("Goalie jersey / Pants / Pads / Catcher / Blocker / Goalie stick", "Goalie equipment styles. The mask is shared across kits; the other styles have home and away choices."),
            new("Player logo", "With Team equipment off and team-color jerseys in both kits, choose a player logo or Use team logo. Premade jerseys keep their artwork."),
            new("Stick / Skate colors", "Skaters own these colors in both kits. Goalies own stick and blocker colors. Blank stick colors use the default stick palette; blank skate/blocker colors follow the team."),
            new("Home / Away", "Choose which kit to preview and edit. This does not save."),
            new("Front / Back", "Change the preview angle only."),
            new("Customise colors / Colour guide", "Edit the selected piece's channels, or read what each channel colors. Premade artwork may not recolor.")],
