            b.Description + " Inherit is On for: " + string.Join(", ", SquadTemplateCatalog.All.Where(t => SquadBehaviors.Enabled(t.Id, b.Id, _ => "")).Select(t => t.Name).DefaultIfEmpty("no available presets")) + "; Off for other presets."))).ToArray(),
        "squads" => new GuideEntry[] {
            new("Add player team", "Create a team directly in this campaign. Opening or adding a player team saves the campaign's working changes first."),
            new("Import player team from library", "Copy a library team and roster. Shared starting-pool conflicts are reported before import."),
            new("Campaign team details", "Click a player team to edit its settings, look, roster and squad behaviors. Campaign working changes are saved before the team opens."),
            new("Use player teams", "Enable the saved custom teams without deleting them when switched off."),
            new("Custom teams only", "Hide the base-game squads for this campaign."),
            new("Starting screens", "In each team's Squad behaviors, Superstar selection and Bench draft control its starting screens. An explicitly empty selected pool skips its screen. Save the team, then edit the shared pools in the campaign. Leave one active skater slot open to receive a starting superstar.")
        }.Concat(SquadTemplateCatalog.All.Select(t => new GuideEntry(t.Name, t.Details))).ToArray(),
        "starting" => [
            new("Copied vanilla candidate lists", "Check the native or custom candidates used by each starting screen. Native entries retain identity; ordinary imported additions are editable field copies. Save campaign keeps selections. An explicitly empty list skips its starting screen."),
            new("Starting bench · 9 slots", PoolChoiceGuidance.Bench + " Each team's Bench draft control decides whether to show the screen; an empty pool skips it."),
            new("Use base-game bench", "Switch between native and custom cards; each view retains its selections. Only the visible pool is active."),
            new("Choose base-game player", "Choose a native bench player. Selecting one already used swaps the two slots."),
            new("Starting superstars · 3 slots", PoolChoiceGuidance.Superstars + " Each team's Superstar selection control decides whether to show the screen; an empty pool skips it."),
            new("+ New player / Import player", "Create a saved player file and put it on the card. The selection still needs saving."),
            new("Edit player", "Save the pool and campaign working changes, then edit this player."),
