            new("Team", "Match/Boss opponent. Unassigned match nodes use base-game opponents; references to missing teams must be fixed."),
            new("Stadium", "World-map stadium artwork only. It does not select the match arena."),
            new("Talent rewards / Relic rewards", "Match nodes only: " + PoolChoiceGuidance.MatchRewards),
